"""Tests for word frequency analysis."""
import pytest
from wordfreq import top_words


class TestTopWords:
    """Test cases for the top_words function."""

    @pytest.mark.parametrize(
        "text,n,expected",
        [
            ("", 5, []),
            ("   ", 5, []),
            ("hello world hello", 2, [("hello", 2), ("world", 1)]),
            ("Hello HELLO hello", 1, [("hello", 3)]),
            ("don't don't won't", 2, [("don't", 2), ("won't", 1)]),
        ],
    )
    def test_word_extraction_and_counting(self, text, n, expected):
        """Test basic word extraction and frequency counting."""
        assert top_words(text, n) == expected

    @pytest.mark.parametrize(
        "text,n,expected",
        [
            ("a b c a b c", 2, [("a", 2), ("b", 2)]),
            ("x y z x y z", 3, [("x", 2), ("y", 2), ("z", 2)]),
            ("aaa aaa bbb", 1, [("aaa", 2)]),
            ("one two one three", 3, [("one", 2), ("three", 1), ("two", 1)]),
        ],
    )
    def test_tie_breaking_alphabetically(self, text, n, expected):
        """Test that ties are broken alphabetically in ascending order."""
        assert top_words(text, n) == expected

    @pytest.mark.parametrize(
        "text,n,expected",
        [
            ("hello world", 0, []),
            ("hello world", -1, []),
            ("hello", -5, []),
            ("", 0, []),
            ("   ", -3, []),
        ],
    )
    def test_edge_cases_n_le_zero(self, text, n, expected):
        """Test behavior when n is zero or negative."""
        assert top_words(text, n) == expected

    @pytest.mark.parametrize(
        "text,n,expected",
        [
            ("hello world hello", 10, [("hello", 2), ("world", 1)]),
            ("a b c d e", 100, [("a", 1), ("b", 1), ("c", 1), ("d", 1), ("e", 1)]),
        ],
    )
    def test_n_larger_than_distinct_words(self, text, n, expected):
        """Test when n exceeds the number of distinct words."""
        assert top_words(text, n) == expected

    @pytest.mark.parametrize(
        "text,n,expected",
        [
            ("don't John's 'tis", 3, [("don't", 1), ("john's", 1), ("'tis", 1)]),
            ("hello---world", 2, [("hello", 1), ("world", 1)]),
            ("hello.world", 2, [("hello", 1), ("world", 1)]),
            ("test: test!", 2, [("test", 2)]),
            ("word1 word2 word1", 2, [("word1", 2), ("word2", 1)]),
        ],
    )
    def test_word_boundary_patterns(self, text, n, expected):
        """Test that only letters and apostrophes form words."""
        assert top_words(text, n) == expected

    @pytest.mark.parametrize(
        "text,n,expected",
        [
            ("a" * 100 + " " + "b" * 50, 2, [("a" * 100, 1), ("b" * 50, 1)]),
            ("x y x", 1, [("x", 2)]),
        ],
    )
    def test_long_words(self, text, n, expected):
        """Test handling of long word fragments."""
        assert top_words(text, n) == expected

